const errorData = $json;
const execution = errorData.execution || {};
const workflow = errorData.workflow || {};
const lastNode = execution.lastNodeExecuted || 'Inconnu';
const errorMsg = execution.error?.message || errorData.message || 'Erreur non spécifiée';

return {
  json: {
    timestamp: new Date().toISOString(),
    workflow_id: workflow.id || 'alpa-recrutement',
    workflow_name: workflow.name || 'Ingestion Candidature',
    noeud_en_echec: lastNode,
    message_erreur: errorMsg,
    details: execution.error || {},
    severite: 'CRITIQUE',
    alerte: `⚠️ Échec d'ingestion e-mail AlpA Ciment sur le nœud [${lastNode}]: ${errorMsg}`
  }
};
